/* v28.xx (cw-cx-preraid-scroll): reserve rows as well as the belt at 4K; an unsold item has a dash, while an unaffordable price stays readable inside a danger border. */
#root #sectormodal #sectorpack{flex:1 0 280px;min-height:280px;padding:8px 0;border-top:1px solid var(--ui-line);border-bottom:1px solid var(--ui-line)}
#root #sectormodal #sectorpack .srplist{min-height:120px;padding-right:8px;scrollbar-gutter:stable}
#root #sectormodal #sectorpack .srbuy.dis{opacity:1;color:var(--tx-1);border-color:var(--danger)}
#root #sectormodal #sectorpack .srbuy.sp{display:grid;place-items:center}
#root #sectormodal #sectorpack .srbuy.sp::after{content:'-';color:var(--tx-2);font:600 16px var(--f-cond)}
#root #sectormodal #srside{overflow-y:auto;padding-right:4px}
/* v28.xx (cw-cx-preraid-scroll): viewport units also grow under menu zoom; divide the pre-raid card margins by that zoom so the 4K card keeps its chosen 5 percent margins. */
#root #sectormodal.modal.ui-win{padding:calc(5vh / var(--sectorzoom,1) + 22px) calc(5vw / var(--sectorzoom,1) + 22px)!important}
#root #sectormodal.modal.ui-win::before{inset:calc(5vh / var(--sectorzoom,1)) calc(5vw / var(--sectorzoom,1))!important}
#root #sectormodal > .ui-foot > .ui-back{top:calc(5vh / var(--sectorzoom,1) + 12px)!important;right:calc(5vw / var(--sectorzoom,1) + 16px)!important}

check:
{v:'VER',what:'the pre-raid pack reserves visible scrolling rows above the belt, with readable unaffordable prices and a dash for unsold items',
 run:function(){
   var snap=null,bad=[],sm=document.getElementById('sectormodal'),q,list,b,sp;
   function shut(){var ms=document.querySelectorAll('.modal.on');for(var j=0;j<ms.length;j++)ms[j].classList.remove('on');}
   try{
     snap=JSON.parse(JSON.stringify(__P()));
     __runPrep();__topClear();__resetCfg();__pinDefaults(0);__cleanProfile();
     q=__P();q.freeKit=0;q.kitPick='mine';q.stash=['medkit','bandage','smoke','frag','plate','gun_carbine','gun_smg'];q.kit=[];q.equipped='fists';q.credits=0;
     __hubEnter();shut();renderSector();openModal('sectormodal');
     var zoom=parseFloat(sm.style.zoom)||1,pad=parseFloat(getComputedStyle(sm).paddingLeft)*zoom;
     if(Math.abs(pad-(innerWidth*0.05+22*zoom))>2)bad.push('pre-raid card margin grows twice under zoom');
     list=sm.querySelector('#sectorpack .srplist');
     if(!list||list.clientHeight<119)bad.push('pack rows have less than 120 px of scrolling space');
     b=sm.querySelector('#sectorpack .srbuy.dis');
     if(!b||+getComputedStyle(b).opacity<0.99)bad.push('unaffordable price is dimmed');
     if(b){var probe=document.createElement('span');probe.style.color='var(--tx-1)';sm.appendChild(probe);var expected=getComputedStyle(probe).color;probe.remove();if(getComputedStyle(b).color!==expected)bad.push('price does not use readable primary text');}
     sp=sm.querySelector('#sectorpack [data-pk="gun_carbine"] .srbuy.sp');
     if(!sp||getComputedStyle(sp,'::after').content.replace(/["']/g,'')!=='-')bad.push('unsold item has no dash');
     return bad.length?bad.join('; '):null;
   }finally{try{shut();if(snap)__applyLoaded(snap);}catch(e){}__topClear();}
 }},
